const a = Symbol('id');
const b = Symbol('id');
console.log(a === b); // false — each call is unique

const user = { name: 'Ada', [a]: 42 };
console.log(user[a]);        // 42
console.log(Object.keys(user)); // ['name'] — symbol key hidden
console.log(Object.getOwnPropertySymbols(user)); // [Symbol(id)]

// Global registry:
const global1 = Symbol.for('app.token');
const global2 = Symbol.for('app.token');
console.log(global1 === global2); // true

const unsafe = 9007199254740993;
console.log(unsafe);                    // 9007199254740992 — wrong!
console.log(Number.isSafeInteger(unsafe)); // false

const safe = 9007199254740993n;
console.log(safe);                      // 9007199254740993n — exact
console.log(safe + 1n);                 // 9007199254740994n

// JSON does not support BigInt natively:
// JSON.stringify({ id: 1n }); // TypeError
const jsonSafe = { id: safe.toString() };

class Collection {
  constructor(items) {
    this._items = items;
  }
  [Symbol.iterator]() {
    return this._items[Symbol.iterator]();
  }
  get [Symbol.toStringTag]() {
    return 'Collection';
  }
}

const c = new Collection([1, 2, 3]);
console.log([...c]); // [1, 2, 3] — Symbol.iterator enables spread

try {
  console.log(1n + 1); // TypeError
} catch (e) {
  console.log('Cannot mix bigint and number');
}
